REF=json.loads((ROOT/'.local/neighborhoods/szeged-raw-review/henits2013/calibration-geographic-reference-local-only.geojson').read_text());SRC=ROOT/'.local/neighborhoods/szeged-raw-review/henits2013/p24-xref249.jpeg'
cs=[('kossuth_outer',[626,330],27186748,[20.1429872,46.2585463],['Kossuth Lajos sugárút','Párizsi körút']),('kalvaria_outer',[599,390],27186846,[20.138692,46.2519321],['Kálvária sugárút','Londoni körút','Moszkvai körút']),('petofi_outer',[603,437],30849519,[20.1383104,46.2470913],['Petőfi Sándor sugárút','Moszkvai körút','Bécsi körút']),('csongradi_outer',[654,210],30752207,[20.1484748,46.2722738],['Csongrádi sugárút','Rókusi körút','Makkosházi körút']),('csongradi_inner',[675,304],30452238,[20.1508524,46.2615273],['Csongrádi sugárút','Brüsszeli körút']),('jozsef_outermost',[720,208],30766136,[20.1592392,46.2725928],['József Attila sugárút','Budapesti körút','Makkosházi körút'])]
