 controls.append({'id':id,'pixel':pixel,'osmNodeId':node,'wgs84':ll,'eov':list(T.transform(*ll)),'observedRoadJunction':names,'sourceWays':[f['id'] for f in fs],'sourcePixelPickingIsManual':True,'pixelPickingDescription':'A few native pixels, plus unquantified cartographic generalization. This is not an absolute uncertainty bound.','correspondenceEvidence':'Henits numbered contour-junction geometry, cross-checked against the matching gray road network in KSH2014 figure1 derived from the same KSH2003 scheme. Actual original OSM road nodes provide geographic positions.','sourcePlacePointUsedForFit':False})
